package ratelimit

import (
	"errors"
	"testing"
	"time"
)

type fakeClock struct {
	t time.Time
}

func (c *fakeClock) Now() time.Time { return c.t }

func (c *fakeClock) Advance(d time.Duration) { c.t = c.t.Add(d) }

func TestNewValidation(t *testing.T) {
	c := &fakeClock{t: time.Unix(0, 0)}
	tests := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  error
	}{
		{"zero capacity", 0, 1, c, ErrNonPositiveCapacity},
		{"negative capacity", -1, 1, c, ErrNonPositiveCapacity},
		{"zero rate", 1, 0, c, ErrNonPositiveRate},
		{"negative rate", 1, -0.5, c, ErrNonPositiveRate},
		{"nil clock", 1, 1, nil, ErrNilClock},
		{"valid", 1, 1, c, nil},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			l, err := New(tc.capacity, tc.rate, tc.clock)
			if !errors.Is(err, tc.wantErr) {
				t.Fatalf("New() error = %v, want %v", err, tc.wantErr)
			}
			if tc.wantErr == nil && l == nil {
				t.Fatal("New() returned nil limiter with nil error")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	base := time.Unix(0, 0)
	tests := []struct {
		name     string
		capacity int
		rate     float64
		steps    []struct {
			advance time.Duration
			n       int
			want    bool
		}
	}{
		{
			name:     "burst up to capacity then denied",
			capacity: 3,
			rate:     1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{0, 1, true},
				{0, 1, true},
				{0, 1, false},
			},
		},
		{
			name:     "refill over time",
			capacity: 2,
			rate:     1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 2, true},   // drain
				{0, 1, false},  // empty
				{time.Second, 1, true},  // 1 token refilled
				{0, 1, false},
				{time.Second, 2, false}, // only 1 refilled, need 2
				{time.Second, 1, true},  // now 2 available
			},
		},
		{
			name:     "tokens capped at capacity",
			capacity: 1,
			rate:     10,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{time.Hour, 1, true}, // refilled (capped at 1)
				{0, 1, false},
			},
		},
		{
			name:     "zero request always allowed",
			capacity: 1,
			rate:     1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{0, 0, true},
				{0, 0, true},
			},
		},
		{
			name:     "negative request denied",
			capacity: 1,
			rate:     1,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, -1, false},
			},
		},
		{
			name:     "fractional refill",
			capacity: 1,
			rate:     2,
			steps: []struct {
				advance time.Duration
				n       int
				want    bool
			}{
				{0, 1, true},
				{400 * time.Millisecond, 1, false}, // 0.8 tokens
				{100 * time.Millisecond, 1, true},  // 1.0 tokens
			},
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			c := &fakeClock{t: base}
			l, err := New(tc.capacity, tc.rate, c)
			if err != nil {
				t.Fatalf("New() error = %v", err)
			}
			for i, s := range tc.steps {
				c.Advance(s.advance)
				if got := l.AllowN(c.Now(), s.n); got != s.want {
					t.Errorf("step %d: AllowN(%v, %d) = %v, want %v", i, c.Now(), s.n, got, s.want)
				}
			}
		})
	}
}

func TestAllowUsesClock(t *testing.T) {
	c := &fakeClock{t: time.Unix(0, 0)}
	l, err := New(1, 1, c)
	if err != nil {
		t.Fatalf("New() error = %v", err)
	}
	if !l.Allow() {
		t.Fatal("first Allow() = false, want true")
	}
	if l.Allow() {
		t.Fatal("second Allow() = true, want false")
	}
	c.Advance(time.Second)
	if !l.Allow() {
		t.Fatal("Allow() after refill = false, want true")
	}
}

func TestConcurrentAccess(t *testing.T) {
	c := &fakeClock{t: time.Unix(0, 0)}
	l, err := New(100, 100, c)
	if err != nil {
		t.Fatalf("New() error = %v", err)
	}
	var wg sync.WaitGroup
	allowed := make([]bool, 200)
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			allowed[i] = l.AllowN(c.Now(), 1)
		}(i)
	}
	wg.Wait()
	count := 0
	for _, a := range allowed {
		if a {
			count++
		}
	}
	if count != 100 {
		t.Errorf("allowed %d requests, want exactly 100", count)
	}
}
